BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L3 — Contradictory evidence discovered after receiving representations
(1, 'Written Representations', 'During the audit of Crestline Manufacturing''s December 31, 2025 financial statements, the engagement team at Baxter & Monroe CPA obtains a signed representation letter confirming no unrecorded liabilities exist. However, a subsequent review of board minutes reveals discussion of a $2.4 million warranty obligation not recorded in the financial statements. Under AU-C 580, the auditor should:', '["Accept the representation letter as conclusive and issue an unmodified opinion", "Investigate the discrepancy, reconsider the reliability of the written representations, and determine whether additional misstatements may exist", "Immediately withdraw from the engagement without further inquiry", "Redate the representation letter to reflect the newly discovered information"]'::jsonb, 1, 'Under AU-C 580.A27, when audit evidence contradicts written representations, the auditor must investigate the inconsistency and reconsider the reliability of other representations obtained. The auditor cannot simply accept the letter as conclusive (choice A) because representations supplement but do not substitute for corroborating evidence. Unlike choice C, withdrawal is not automatic — the auditor must first investigate and evaluate the implications.', 'hard', 3),

-- Q2: easy / L1 — Written representations supplement other evidence
(1, 'Written Representations', 'In the context of an audit, written representations from management are best described as:', '["The most reliable form of evidence available to the auditor", "A necessary source of audit evidence that supplements but does not substitute for other audit procedures", "Optional documentation that the auditor may request at their discretion", "A legal contract between the auditor and the entity being audited"]'::jsonb, 1, 'Under AU-C 580.04, written representations are a necessary source of audit evidence that complement other procedures but do not replace them. Unlike choice A, management representations are among the least reliable evidence types because they are internal and self-reported. Choice C is incorrect because representations are required, not optional, on every audit engagement.', 'easy', 1),

-- Q3: easy / L2 — Completeness assertion in the representation letter
(1, 'Written Representations', 'During the audit of Waverly Technology Corp., the engagement partner at Sterling & Hayes CPA reviews the draft management representation letter. The partner asks a staff auditor to identify which assertion the following representation supports: "All transactions have been recorded and are reflected in the financial statements." This representation most directly addresses the assertion of:', '["Existence or occurrence", "Rights and obligations", "Completeness", "Valuation and allocation"]'::jsonb, 2, 'Under AU-C 580.11, management''s representation that all transactions have been recorded directly supports the completeness assertion — confirming that nothing has been omitted from the financial statements. Choice A is incorrect because existence addresses whether assets and transactions are real, which is the opposite direction of testing. Completeness concerns understatement, while existence concerns overstatement.', 'easy', 2),

-- Q4: medium / L3 — Management responsibility when using specialist for estimates
(1, 'Written Representations', 'Highland Properties Inc. engaged an independent appraiser to value its commercial real estate portfolio at $48 million for its December 31, 2025 financial statements. The engagement team at Powell & Grant CPA requests that the management representation letter address management''s responsibility for fair value estimates. Management responds that the appraiser bears full responsibility since the appraiser performed the valuation. Under AU-C 580, the auditor should explain that:', '["The appraiser''s involvement eliminates the need for management to provide representations about fair value", "Only the appraiser needs to provide written representations about the valuation methodology", "Management may delegate the estimation to a specialist but must still provide a representation about the fair value", "Management retains responsibility for the reasonableness of significant assumptions and must include the estimate in their representations regardless of the specialist''s involvement"]'::jsonb, 3, 'Under AU-C 580.11, management is responsible for the financial statements and all estimates therein, even when a specialist performs the underlying work. Representations must acknowledge this responsibility. Choice A is incorrect because using a specialist does not relieve management of its obligation to include fair value representations. Management cannot delegate its financial reporting responsibility.', 'medium', 3),

-- Q5: easy / L1 — "To the best of knowledge and belief" qualifier
(1, 'Written Representations', 'In a management representation letter, the phrase "to the best of our knowledge and belief" is used to:', '["Limit management''s legal liability for inaccurate statements in the letter", "Acknowledge that certain representations are based on management''s awareness and may not cover matters beyond their knowledge", "Indicate that management has not verified the information provided to the auditor", "Signal that the representations should be treated as unreliable by the auditor"]'::jsonb, 1, 'Under AU-C 580.A8, the "to the best of our knowledge and belief" qualifier is used for matters where exhaustive knowledge may not be possible, such as fraud or noncompliance with laws. It recognizes the inherent limits of management''s awareness. Unlike choice A, the qualifier does not serve as a legal liability shield — it reflects practical limitations on management''s knowledge.', 'easy', 1),

-- Q6: medium / L3 — Entity-specific representations for environmental liabilities
(1, 'Written Representations', 'Oakridge Chemical Corp. has three active sites subject to environmental remediation under state regulations. During the December 31, 2025 audit, the engagement team at Whitmore & Associates requests specific representations about environmental liabilities. Management provides a general statement that "all known liabilities are recorded" but declines to address the remediation sites individually. The auditor should:', '["Request management to include specific representations about the remediation sites because the general statement may not adequately address known significant exposures", "Accept the general statement because AU-C 580 does not require entity-specific representations", "Withdraw from the engagement due to management''s refusal to provide specific representations", "Issue a qualified opinion solely based on the omission of specific environmental representations"]'::jsonb, 0, 'Under AU-C 580.13, the auditor may request additional representations beyond the standard items when specific circumstances warrant them. Significant environmental exposures constitute such circumstances requiring tailored representations. Choice B is incorrect because AU-C 580.A12 contemplates additional representations tailored to the entity''s operations. Withdrawal (choice C) is premature when management may agree upon further discussion.', 'medium', 3),

-- Q7: hard / L4 — Evaluating modified representation vs. additional procedures
(1, 'Written Representations', 'During the audit of Pinnacle Software Inc.''s December 31, 2025 financial statements, management provides a representation letter that qualifies the revenue recognition representation by stating: "Revenue has been recognized in accordance with our policies, except for contracts with Enterprise Solutions LLC, which are subject to ongoing legal interpretation." The engagement partner at Radcliffe & Stone CPA must evaluate the appropriate response. The auditor should:', '["Accept the qualification without modification because management has disclosed the specific area of uncertainty", "Issue a disclaimer of opinion because the modified representation constitutes a scope limitation", "Assess whether the qualification represents a reasonable uncertainty or an attempt to limit scope, perform targeted procedures on the Enterprise Solutions contracts, and determine whether the qualification affects the audit opinion", "Remove the qualification from the representation letter and obtain an unqualified version before issuing the report"]'::jsonb, 2, 'Under AU-C 580.20, a qualification in representations requires the auditor to evaluate its nature and significance rather than automatically accepting or rejecting it. The auditor must determine whether additional evidence can compensate for the qualified representation. Choice B is too extreme — a disclaimer is warranted only if the qualification constitutes a material scope limitation that cannot be resolved through alternative procedures.', 'hard', 4),

-- Q8: hard / L4 — Group audit component management representations
(1, 'Written Representations', 'Meridian Holdings Inc. is audited by Lawson & Blake CPA. Meridian has three wholly owned subsidiaries, each with separate management teams. The component auditors of Apex Corp., one subsidiary contributing 40% of consolidated revenue, refuse to obtain a separate management representation letter from Apex''s local management, arguing that Meridian''s consolidated representation letter is sufficient. The group engagement partner should:', '["Accept the consolidated representation letter as sufficient because Meridian''s management takes responsibility for the entire group", "Issue a qualified opinion specifically referencing the lack of component-level representations from Apex", "Withdraw from the group audit because a single missing component representation invalidates the entire engagement", "Require the component auditor to obtain representations from Apex''s management because AU-C 600 requires component management to acknowledge responsibility for the component financial information"]'::jsonb, 3, 'Under AU-C 600.42, the group engagement team should request component management to provide written representations covering matters relevant to the component''s financial information. Choice A is incorrect because consolidated management representations do not substitute for component-level representations when the component is significant. Apex''s 40% revenue contribution makes it a significant component requiring its own representations.', 'hard', 4),

-- Q9: medium / L2 — Internal controls responsibility representation
(1, 'Written Representations', 'During the audit of Bridgewater Financial Group''s December 31, 2025 financial statements, the engagement team at Kendall & Park CPA reviews the management representation letter to ensure it includes all required items. The representation about internal controls typically states that management acknowledges its responsibility for:', '["Guaranteeing that internal controls will prevent all material misstatements in the financial statements", "The design, implementation, and maintenance of internal control relevant to the preparation of financial statements free from material misstatement", "Ensuring that the auditor has tested all key controls during the audit", "Certifying that no control deficiencies existed during the period under audit"]'::jsonb, 1, 'Under AU-C 580.11(b), management must acknowledge its responsibility for designing, implementing, and maintaining internal control relevant to preparing financial statements free from material misstatement. Choice A is incorrect because internal controls provide reasonable, not absolute, assurance. Management does not guarantee the prevention of all misstatements — it acknowledges its responsibility for the control system.', 'medium', 2),

-- Q10: medium / L2 — Access to records vs. completeness distinction
(1, 'Written Representations', 'The engagement team at Foster & Blake CPA is reviewing the management representation letter for Redwood Logistics Inc.''s December 31, 2025 audit. A junior auditor asks about the distinction between two specific representations: one about providing the auditor access to all records, and another about all transactions being reflected in the financial statements. The key difference is:', '["The access representation is required only for first-year audits, while the completeness representation applies to all engagements", "The access representation addresses management''s intent, while the completeness representation addresses the auditor''s responsibility", "Both representations serve the same purpose and are interchangeable in the letter", "The access representation confirms the auditor received all requested documents and data, while the completeness representation confirms that no transactions or events were omitted from the financial statements"]'::jsonb, 3, 'Under AU-C 580.11, the access representation (AU-C 580.11(a)) relates to providing all relevant information and documents, while the completeness representation (AU-C 580.11(c)) confirms that all transactions have been recorded. Choice C is incorrect because they address different aspects — one concerns document availability and the other concerns the integrity of recorded financial activity.', 'medium', 2),

-- Q11: medium / L2 — Compliance with laws and regulations representation
(1, 'Written Representations', 'During the audit of Atlas Pharmaceuticals Inc.''s December 31, 2025 financial statements, the engagement team at Harper & Quinn CPA includes a representation about regulatory compliance in the management letter. This representation about compliance with laws and regulations is important to the audit because it:', '["Supports the auditor''s assessment of whether noncompliance could have a material effect on the financial statements", "Transfers legal liability for noncompliance from management to the auditor", "Eliminates the need for the auditor to perform any procedures related to illegal acts", "Provides conclusive evidence that the entity has complied with all applicable laws"]'::jsonb, 0, 'Under AU-C 580.11(e) and AU-C 250, management''s representation about compliance helps the auditor evaluate the risk that noncompliance could materially affect the financial statements. Choice C is incorrect because representations supplement but do not replace the auditor''s responsibility to consider laws and regulations. Choice D overstates the evidentiary value — representations are not conclusive proof of compliance.', 'medium', 2),

-- Q12: medium / L2 — Going concern representation
(1, 'Written Representations', 'During the audit of Crestview Manufacturing Corp.''s December 31, 2025 financial statements, the engagement team at Bryant & Collins CPA requests a representation about going concern. Management asks what specific information this representation should address. The going concern representation should confirm that management:', '["Certifies the entity will continue operating for at least five years from the balance sheet date", "Has prepared a formal business continuity plan approved by the board of directors", "Has assessed the entity''s ability to continue as a going concern and disclosed any substantial doubt to the auditor", "Has obtained financing commitments that ensure uninterrupted operations through the next fiscal year"]'::jsonb, 2, 'Under AU-C 580.11 and AU-C 570, the going concern representation requires management to confirm its assessment of the entity''s ability to continue as a going concern for a reasonable period and to disclose any known uncertainties. Choice A is incorrect because the assessment period is typically one year from the financial statement date, not five years. The representation addresses assessment and disclosure, not assurances of perpetual operations.', 'medium', 2),

-- Q13: medium / L2 — Alternative signatories for nonprofit governance
(1, 'Written Representations', 'Northfield Community Hospital, a nonprofit entity, is audited by Sullivan & Park CPA for the year ended December 31, 2025. The hospital has no CEO or CFO — instead, it is governed by a board of trustees with an executive director and a finance director. The engagement partner asks who should sign the management representation letter. Under AU-C 580, the appropriate signatories are:', '["The chair of the board of trustees alone, as the highest governing authority", "The external legal counsel for the hospital, as an independent third party", "Any two members of the hospital staff regardless of their roles", "The executive director and finance director, as the individuals with overall responsibility for financial and operational matters"]'::jsonb, 3, 'Under AU-C 580.09, the representation letter should be signed by members of management with appropriate responsibilities — typically the highest-level individuals responsible for financial and operational matters. Choice A is incorrect because the board chair is part of governance, not management. In the absence of CEO/CFO titles, the equivalent executives (executive director, finance director) fulfill this role.', 'medium', 2),

-- Q14: hard / L4 — Multi-period representations for comparative financials
(1, 'Written Representations', 'Elmsford Capital Advisors has been audited by Chambers & Walsh CPA for three consecutive years. In the December 31, 2025 representation letter, management includes representations that address only the current year. The engagement partner notes that certain prior-year comparative amounts are presented in the financial statements. The partner should evaluate whether:', '["Only current-year representations are needed because prior-year representations were already obtained in previous engagements", "Prior-year representations automatically carry forward and need not be re-requested", "The prior-year auditor must provide a separate representation letter covering the comparative amounts", "The representation letter should cover all periods presented in the financial statements, including any representations relevant to comparative amounts and restatements"]'::jsonb, 3, 'Under AU-C 580.15, written representations cover all periods referred to in the auditor''s opinion. When comparative financial statements are presented, management must provide representations covering all periods. Choice A is incorrect because prior-period representations do not persist — they must be reaffirmed for each set of financial statements on which the auditor is currently reporting.', 'hard', 4),

-- Q15: medium / L3 — Uncorrected misstatements and materiality acknowledgment
(1, 'Written Representations', 'During the audit of Greystone Financial Corp.''s December 31, 2025 financial statements, the engagement team at Nelson & Hayes CPA identifies three uncorrected misstatements totaling $85,000, each individually and in aggregate immaterial. The partner prepares to finalize the representation letter. Under AU-C 580, the representation letter should:', '["Exclude mention of the uncorrected misstatements because they are immaterial", "Include a list of the uncorrected misstatements and management''s acknowledgment that their effects, individually and in the aggregate, are immaterial to the financial statements", "Require management to correct all three misstatements regardless of materiality before signing", "Include a disclaimer that the auditor takes no responsibility for the uncorrected amounts"]'::jsonb, 1, 'Under AU-C 580.11(d), the representation letter must include management''s acknowledgment that the effects of uncorrected misstatements are immaterial, with the misstatements summarized or attached. Choice A is incorrect because AU-C 580 requires disclosure of uncorrected misstatements in the representation letter regardless of individual immateriality. Management must formally acknowledge their aggregate immateriality.', 'medium', 3),

-- Q16: medium / L3 — Oral representations contradicting documentary evidence
(1, 'Written Representations', 'During the audit of Summerfield Industries'' December 31, 2025 financial statements, the controller verbally tells the engagement team at Carson & Drew CPA that a major vendor dispute has been resolved for $150,000. However, the signed representation letter states that all litigation and claims have been properly disclosed and no additional amounts are owed. The auditor discovers no documentation supporting the resolution. The auditor should:', '["Accept the representation letter as the definitive record and disregard the oral statement", "Document the oral statement in the workpapers and rely on it as the more current information", "Investigate the discrepancy between the oral statement and the representation letter, and obtain corroborating evidence to determine the actual status of the dispute", "Request a new representation letter that incorporates the verbal disclosure about the vendor dispute"]'::jsonb, 2, 'Under AU-C 580.A27, when inconsistencies exist between representations and other audit evidence, the auditor must investigate the discrepancy. Neither the oral statement nor the written representation can be accepted at face value without corroboration. Choice A is incorrect because representations do not override contradictory evidence — the auditor must resolve inconsistencies through additional procedures before concluding.', 'medium', 3),

-- Q17: hard / L4 — Management bias in estimates pattern
(1, 'Written Representations', 'During the audit of Lakeview Insurance Corp.''s December 31, 2025 financial statements, the engagement team at Crawford & Pierce CPA notices that management''s loss reserve estimates have consistently fallen at the most favorable end of the reasonable range over the past three years. Management provides a representation letter confirming the reserves are their best estimate. The partner should evaluate whether:', '["The pattern of favorable estimates indicates possible management bias that warrants skepticism about the reliability of the related representations and additional substantive procedures", "The representations about reserves are sufficient because management has acknowledged responsibility for the estimates each year", "The auditor should accept management''s judgment because the estimates fall within the reasonable range", "The representation letter should be revised to include the specific range of reasonable estimates for each reserve"]'::jsonb, 0, 'Under AU-C 580.A7 and AU-C 540.17, a pattern of estimates consistently at the favorable end of the range may indicate management bias. The auditor must exercise heightened skepticism and cannot simply rely on representations when bias indicators exist. Choice C is incorrect because falling within the reasonable range does not preclude bias — the systematic pattern itself requires investigation beyond the representation letter.', 'hard', 4),

-- Q18: medium / L3 — Subsequent events representation content
(1, 'Written Representations', 'Thornbury Enterprises'' December 31, 2025 audit is nearing completion. The engagement team at Mitchell & Carr CPA prepares the management representation letter for signature on March 15, 2026, the planned report date. Management asks what the subsequent events representation should cover. Under AU-C 580, the subsequent events representation should confirm that management has:', '["Informed the auditor of all events occurring between December 31, 2025 and the date of the representation letter that may require adjustment or disclosure in the financial statements", "Provided assurance that no events after December 31, 2025 will require future restatement of the financial statements", "Reviewed only those subsequent events that have a direct financial impact exceeding materiality thresholds", "Delegated subsequent events monitoring entirely to the entity''s legal counsel through the report date"]'::jsonb, 0, 'Under AU-C 580.11 and AU-C 560, the subsequent events representation requires management to confirm disclosure of all events between the balance sheet date and the representation letter date that may affect the financial statements. Choice B is incorrect because management cannot guarantee the absence of future events requiring restatement — the representation covers only events known through the letter date.', 'medium', 3),

-- Q19: easy / L1 — Completeness of information meaning
(1, 'Written Representations', 'In a management representation letter, "completeness" of information provided to the auditor means:', '["The financial statements contain only verified and confirmed transactions", "Management has provided the auditor with all relevant information and access agreed upon in the terms of the engagement", "Every transaction has been audited and approved by the board of directors", "The auditor has independently verified every balance in the general ledger"]'::jsonb, 1, 'Under AU-C 580.11(a), the completeness representation confirms management has provided all relevant information and access to records as agreed in the engagement terms. Choice A confuses completeness with verification. Unlike choice D, completeness pertains to what management has disclosed and made available, not what the auditor has independently verified through substantive testing.', 'easy', 1),

-- Q20: easy / L1 — Standard governing written representations
(1, 'Written Representations', 'The authoritative AICPA standard that specifically governs written representations in a financial statement audit is:', '["AU-C 315, Understanding the Entity and Its Environment", "AU-C 560, Subsequent Events and Subsequently Discovered Facts", "AU-C 580, Written Representations", "AU-C 700, Forming an Opinion and Reporting on Financial Statements"]'::jsonb, 2, 'AU-C 580 is the authoritative AICPA standard that specifically addresses the auditor''s responsibilities regarding written representations from management during an audit of financial statements. Choice B is incorrect because AU-C 560 addresses subsequent events, not representations. While representation letters may reference topics from other standards, AU-C 580 is the governing standard for the letter itself.', 'easy', 1),

-- Q21: easy / L1 — Primary purpose of written representations
(1, 'Written Representations', 'The primary purpose of obtaining written representations from management during an audit is to:', '["Create a binding legal contract that holds management liable for all misstatements", "Replace the need for substantive testing in low-risk audit areas", "Satisfy regulatory requirements imposed by the Securities and Exchange Commission", "Confirm management''s responsibility for the financial statements and acknowledge providing all relevant information to the auditor"]'::jsonb, 3, 'Under AU-C 580.03-.04, the primary purpose of written representations is to confirm management''s acknowledgment of its responsibilities and to document that management has provided all relevant information. Choice B is incorrect because representations supplement, not replace, substantive procedures. While representations have legal significance, their primary audit purpose is evidentiary, not contractual (choice A).', 'easy', 1),

-- Q22: medium / L2 — Explicit vs. implicit representations
(1, 'Written Representations', 'During the audit of Silverstone Corp.''s December 31, 2025 financial statements, the engagement team at Drake & Mason CPA distinguishes between explicit and implicit representations in the management letter. Management''s statement that "we have provided you access to all minutes of shareholders'' and directors'' meetings" is an example of a(n):', '["Explicit representation because it directly and specifically addresses a particular matter", "Implicit representation because it merely accompanies the financial statements", "Negative representation because it asserts the absence of withheld information", "Conditional representation because it depends on the auditor''s verification"]'::jsonb, 0, 'Under AU-C 580.A5, explicit representations are direct written statements about specific matters included in the representation letter. The statement clearly and specifically addresses access to meeting minutes. Choice B is incorrect because implicit representations arise indirectly from the preparation and presentation of financial statements, not from direct written statements in the letter.', 'medium', 2),

-- Q23: hard / L4 — Disclaimer when one required representation is withheld
(1, 'Written Representations', 'During the audit of Westbrook Dynamics Inc.''s December 31, 2025 financial statements, management provides all required written representations except the representation about fraud. The CFO states that legal counsel has advised against making any written statements about fraud due to pending litigation. All other audit evidence indicates no fraud exists. The engagement partner at Fletcher & Dunn CPA must determine the appropriate action. The auditor should:', '["Accept the omission of the fraud representation because all other audit evidence supports the absence of fraud", "Issue a disclaimer of opinion because management''s refusal to provide a required representation constitutes a scope limitation, regardless of other evidence obtained", "Issue a qualified opinion limited to the fraud assertion while providing an unmodified opinion on all other areas", "Obtain a written representation from legal counsel to substitute for management''s fraud representation"]'::jsonb, 1, 'Under AU-C 580.19-.20, if management does not provide one or more of the requested written representations, the auditor must disclaim an opinion. The fraud representation is specifically required under AU-C 580.11, and refusal to provide it constitutes a scope limitation. Choice A is incorrect because corroborating evidence does not eliminate the need for required written representations — the obligation is absolute.', 'hard', 4),

-- Q24: medium / L2 — Commitments and contingencies representation
(1, 'Written Representations', 'During the audit of Ironbridge Construction Corp.''s December 31, 2025 financial statements, the engagement team at Phelps & Garner CPA reviews the representation letter for specific items related to contingencies. The representation about contingent liabilities typically requires management to confirm that:', '["All contingent liabilities have been resolved before the financial statement date and no further disclosure is needed", "The entity''s insurance coverage is adequate to cover all potential contingent losses", "All known contingent liabilities have been disclosed or accrued in accordance with the applicable financial reporting framework", "External legal counsel has confirmed the expected outcome of all pending legal matters"]'::jsonb, 2, 'Under AU-C 580.11 and ASC 450, the contingency representation requires management to confirm that all known contingent liabilities have been properly disclosed or accrued following the applicable accounting standards. Choice A is incorrect because contingent liabilities need not be resolved — they must be disclosed or accrued as appropriate. Legal counsel cannot guarantee litigation outcomes (choice D).', 'medium', 2),

-- Q25: medium / L3 — Representation letter received after report date
(1, 'Written Representations', 'The engagement team at Barrett & Cole CPA completed the audit of Hawthorn Medical Group''s December 31, 2025 financial statements and dated the auditor''s report March 10, 2026. Due to the CFO''s travel schedule, the signed management representation letter was not received until March 15, 2026. The engagement partner should:', '["Accept the March 15 letter because the five-day delay is immaterial", "Backdate the representation letter to March 10 to align with the audit report date", "Issue the report without the representation letter and obtain it later as a supplemental document", "Either obtain a new letter dated March 10 or delay the report until March 15 and update subsequent events procedures through that date"]'::jsonb, 3, 'Under AU-C 580.14, the representation letter must be dated no later than the date of the auditor''s report. If the letter is dated after the report date, the auditor should either obtain a properly dated letter or extend the report date to match. Choice B is incorrect because backdating a representation letter would misrepresent when management actually made the representations, undermining evidence integrity.', 'medium', 3),

-- Q26: easy / L1 — Written representations required for every audit
(1, 'Written Representations', 'Under generally accepted auditing standards, written representations from management are required:', '["Only when the auditor identifies specific areas of concern during the audit", "For every audit of financial statements, regardless of the engagement circumstances", "Only for publicly traded companies subject to PCAOB oversight", "Only during the initial year of an audit engagement"]'::jsonb, 1, 'Under AU-C 580.09, written representations are required for all audits of financial statements performed under generally accepted auditing standards. Choice A is incorrect because representations are mandatory regardless of whether specific concerns exist. Choice C is incorrect because AU-C 580 applies to all AICPA audits, not just public company engagements governed by PCAOB standards.', 'easy', 1),

-- Q27: easy / L1 — Who determines matters to include in the letter
(1, 'Written Representations', 'The matters to be included in the management representation letter are determined by:', '["The auditor, based on the requirements of auditing standards and matters relevant to the specific engagement", "Management alone, based on what they deem appropriate to disclose", "The entity''s legal counsel, based on potential litigation risk", "The audit committee, based on corporate governance requirements"]'::jsonb, 0, 'Under AU-C 580.06-.11, the auditor is responsible for determining which representations to request, guided by the requirements of AU-C 580 and the specific circumstances of the engagement. Choice B is incorrect because management does not unilaterally decide what to include — the auditor specifies the required representations. Management''s role is to provide the requested representations.', 'easy', 1),

-- Q28: easy / L1 — Title to assets representation purpose
(1, 'Written Representations', 'A management representation about title to assets is designed to provide evidence that:', '["All assets have been physically inspected and counted by management during the period", "Assets are recorded at their current fair market value in the financial statements", "The entity has legal ownership of or rights to assets reported in the financial statements", "All asset purchases were approved by the board of directors during the year"]'::jsonb, 2, 'Under AU-C 580.11 and AU-C 315, the representation about title supports the rights and obligations assertion — confirming that the entity owns or has legal rights to the assets reported in the financial statements. Choice A is incorrect because it addresses existence procedures, not ownership rights. Choice B is incorrect because it addresses the valuation assertion, which is a separate matter from legal title to assets.', 'easy', 1),

-- Q29: medium / L3 — Incomplete fair value representations for material balance
(1, 'Written Representations', 'During the audit of Cascade Investments LLC''s December 31, 2025 financial statements, management provides a representation about Level 3 fair value measurements but omits any discussion of the significant unobservable inputs and valuation models used. The engagement team at Werner & Associates notes that the $12 million Level 3 portfolio represents 25% of total assets. The auditor should:', '["Request management to expand the representation to include the significant assumptions, inputs, and models used for Level 3 measurements because the omission creates uncertainty about a material balance", "Accept the representation as sufficient because management has acknowledged the Level 3 classification", "Perform additional substantive testing to compensate for the incomplete representation without requesting a revised letter", "Issue an adverse opinion because the incomplete representation indicates a pervasive misstatement"]'::jsonb, 0, 'Under AU-C 580.13 and AU-C 540, when estimates are significant, the auditor should request specific representations about the methods, assumptions, and data underlying them. A balance representing 25% of total assets warrants detailed representations. Choice B is incorrect because acknowledging the classification without addressing valuation methodology is insufficient for a material estimate requiring judgment.', 'medium', 3),

-- Q30: medium / L2 — Representation letter vs. engagement letter distinction
(1, 'Written Representations', 'A first-year staff auditor at Calloway & Associates asks the engagement partner to explain the difference between the management representation letter and the engagement letter. The key distinction is that the engagement letter:', '["Is signed before the audit begins and establishes the terms and responsibilities for the engagement, while the representation letter is obtained near the end of the audit and provides audit evidence", "Serves as audit evidence about management''s assertions, while the representation letter defines the scope of the audit", "Is optional and provided at the auditor''s discretion, while the representation letter is mandatory under AU-C 580", "Is signed by the audit committee, while the representation letter is signed by external legal counsel"]'::jsonb, 0, 'Under AU-C 210 and AU-C 580, the engagement letter is executed before the audit begins and establishes terms, objectives, and responsibilities. The representation letter is obtained at or near audit completion and serves as audit evidence. Choice B is incorrect because it reverses the purpose of each document. Both are required — the engagement letter under AU-C 210 and the representation letter under AU-C 580.', 'medium', 2)
;

COMMIT;
